// ---------------------------------------------------------------------------------------------
// The recorded parser, and how a circuit is read back
// ---------------------------------------------------------------------------------------------

const tokensOf = text => {
  if (!recorded[text]) throw new Error('No recorded parse for: ' + text)
  return recorded[text].tokens.map(([word, start, pos, tag, dep, head, lemma], i) => ({i, text: word, start, end: start + word.length, pos, tag, dep, head, lemma}))
}
const beamOf = text => {
  const tokens = tokensOf(text)
  const alternatives = recorded[text].beam.map(([score, arcs]) => ({score,
    tokens: arcs.split(' ').map((arc, i) => ({...tokens[i], dep: arc.split('>')[0], head: Number(arc.split('>')[1])}))}))
  return {tokens, alternatives}
}
/** A dependency provider that replays the recorded parses: no Python, no model. */
const replay = {async open() {
  return {metadata: {library: 'recorded'}, parse: async text => tokensOf(text), parseBeam: async text => beamOf(text), close: async () => {}}
}}
const strategies = [neuralDependencies, spacyDirect, spacyBeam]
const messages = Object.keys(recorded)

/** The wires of a circuit: {id, type, form, words(key) → [text], refs(key) → [wire]}. */
function read(sop) {
  const byId = new Map()
  const wires = parseCircuit(sop).map(wire => {
    const values = key => wire.slots.filter(slot => slot[0] === key).map(slot => slot[1])
    return {id: wire.id, type: wire.type.slice('syntax.'.length), form: values('form')[0], attachment: values('attachment')[0],
      words: key => values(key).map(value => JSON.parse(value)), refs: key => values(key).map(value => byId.get(value.slice(1)))}
  })
  for (const wire of wires) byId.set(wire.id, wire)
  const of = type => wires.filter(wire => wire.type === type)
  return {
    wires, clauses: of('clause'), nominals: of('nominal'), relations: of('relation'), coordinations: of('coordination'),
    clause: verb => of('clause').find(wire => wire.words('verb')[0] === verb),
    nominal: head => of('nominal').find(wire => wire.words('head')[0] === head),
    relation: marker => of('relation').find(wire => wire.words('marker')[0] === marker)
  }
}
async function circuits(strategy, texts, options = {}) {
  const reader = await createReader({strategy, syntaxModel: replay, ...options})
  try {
    const out = new Map()
    for (const text of texts) out.set(text, await reader.propose(text))
    return out
  } finally {
    await reader.close()
  }
}

// ---------------------------------------------------------------------------------------------
// Every strategy returns one valid circuit, with no knowledge repository
// ---------------------------------------------------------------------------------------------

test('the dependency strategies are run with no knowledge repository', () => {
  assert.equal(process.env.SOP_KNOWLEDGE_DIR, undefined, 'run this test with SOP_KNOWLEDGE_DIR unset')
  assert.ok(messages.length >= 12)
  for (const strategy of strategies) assert.equal(strategy.schema, 'syntax', strategy.name)
  assert.deepEqual(strategies.map(strategy => strategy.name), ['neural-dependencies', 'spacy-direct', 'spacy-beam'])
})

for (const strategy of strategies) {
  test(`${strategy.name} returns one valid syntax circuit for each of ${messages.length} messages`, async () => {
    const results = await circuits(strategy, messages)
    for (const [text, result] of results) {
      assert.equal(result.engine, strategy.name)
      assert.equal(result.schema, 'syntax')
      assert.equal(result.error, null, text)
      assert.equal(result.candidates.length, 1, text)
      assert.deepEqual(result.rejected, [], text)
      const [{sop, check}] = result.candidates
      assert.equal(check.valid, true, text)
      // checked again here, by the contract alone: every word once, punctuation in no wire
      const again = validateSyntax(text, sop)
      assert.deepEqual(again.findings, [], text)
      assert.equal(again.placements.reduce((sum, place) => sum + place.last - place.first + 1, 0), wordsOf(text).length, text)
      assert.doesNotMatch(sop, /\bnlu\.|w\.request/u, text)
      assert.ok(sop.split('\n').every(line => /^@[a-z]\d+ syntax\.(?:clause|nominal|relation|coordination) /u.test(line)), sop)
    }
  })

  test(`${strategy.name} writes what the parse shows: clauses, nominals, relations, coordinations`, async () => {
    const results = await circuits(strategy, messages)
    const of = text => read(results.get(text).candidates[0].sop)

    // two commands joined by "and"; "next to" is one marker; "bigger" modifies the clause of "make"
    let c = of('move the blue box next to the red circle and make it bigger')
    assert.deepEqual(c.clauses.map(wire => [wire.form, wire.words('verb')[0]]), [['imperative', 'move'], ['imperative', 'make']])
    assert.deepEqual(c.coordinations[0].refs('conjunct'), [c.clause('move'), c.clause('make')])
    assert.deepEqual(c.coordinations[0].words('conjunction'), ['and'])
    assert.deepEqual(c.nominal('box').words('dependent'), ['the', 'blue'])
    assert.deepEqual(c.clause('move').refs('complement'), [c.nominal('box')])
    assert.equal(c.relation('next to').refs('to')[0], c.nominal('circle'))
    assert.deepEqual(c.clause('make').words('modifier'), ['bigger'])
    assert.deepEqual(c.clause('make').refs('complement'), [c.nominal('it')])

    // Rule 3: the second pair shares the verb of the first
    c = of('make A blue and B green')
    const [shared] = c.clauses.filter(wire => wire.form === 'fragment')
    assert.deepEqual(shared.refs('ellipsis'), [c.clause('make')])
    assert.deepEqual([shared.words('modifier'), shared.refs('complement')], [['green'], [c.nominal('B')]])
    assert.deepEqual([c.clause('make').words('modifier'), c.clause('make').refs('complement')], [['blue'], [c.nominal('A')]])
    assert.deepEqual(c.coordinations[0].refs('conjunct'), [c.clause('make'), shared])

    // Rule 4: the measure is a complement and the relation starts at it
    c = of('put the lamp two inches from the edge')
    assert.deepEqual(c.clause('put').refs('complement'), [c.nominal('lamp'), c.nominal('inches')])
    assert.deepEqual(c.nominal('inches').words('dependent'), ['two'])
    assert.deepEqual([c.relation('from').refs('from')[0], c.relation('from').refs('to')[0]], [c.nominal('inches'), c.nominal('edge')])

    // two relations joined by "but"; "not" negates the second only
    c = of('put it near Ben but not behind Jo')
    assert.deepEqual(c.coordinations[0].refs('conjunct'), [c.relation('near'), c.relation('behind')])
    assert.deepEqual(c.coordinations[0].words('conjunction'), ['but'])
    assert.deepEqual([c.relation('near').words('negation'), c.relation('behind').words('negation')], [[], ['not']])
    assert.deepEqual(c.clause('put').words('negation'), [])
    assert.equal(c.relation('behind').refs('from')[0], c.clause('put'))

    // Rule 5: the "to" of an infinitive marks the relation to the nonfinite clause
    c = of('I want to delete it')
    assert.deepEqual([c.clause('want').form, c.clause('delete').form], ['declarative', 'nonfinite'])
    assert.deepEqual([c.relation('to').refs('from')[0], c.relation('to').refs('to')[0]], [c.clause('want'), c.clause('delete')])
    assert.deepEqual(c.clause('want').refs('subject'), [c.nominal('I')])
    c = of('to fix the details, edit the members')
    assert.deepEqual([c.relation('to').refs('from')[0], c.relation('to').refs('to')[0]], [c.clause('edit'), c.clause('fix')])
    assert.deepEqual([c.clause('edit').form, c.clause('fix').form], ['imperative', 'nonfinite'])

    // the grammatical subject, the auxiliary, and the agent as the end of a relation marked "by"
    c = of('the box was moved by Ana')
    assert.deepEqual([c.clause('moved').form, c.clause('moved').words('auxiliary'), c.clause('moved').refs('subject')], ['declarative', ['was'], [c.nominal('box')]])
    assert.deepEqual([c.relation('by').refs('from')[0], c.relation('by').refs('to')[0]], [c.clause('moved'), c.nominal('Ana')])

    // a question word stands where its grammar puts it
    c = of('what colour is the castle?')
    assert.equal(c.clause('is').form, 'interrogative')
    assert.deepEqual(c.nominal('colour').words('dependent'), ['what'])
    assert.deepEqual([c.clause('is').refs('complement'), c.clause('is').refs('subject')], [[c.nominal('colour')], [c.nominal('castle')]])
    c = of('where is it?')
    assert.deepEqual([c.clause('is').form, c.clause('is').words('modifier'), c.clause('is').refs('subject')], ['interrogative', ['where'], [c.nominal('it')]])
    c = of('how many groups have I made?')
    assert.deepEqual(c.nominal('groups').words('dependent'), ['how', 'many'])
    assert.deepEqual([c.clause('made').form, c.clause('made').words('auxiliary')], ['interrogative', ['have']])
    c = of('Could you move it?')
    assert.deepEqual([c.clause('move').form, c.clause('move').words('auxiliary'), c.clause('move').refs('subject'), c.clause('move').refs('complement')],
      ['interrogative', ['Could'], [c.nominal('you')], [c.nominal('it')]])

    // negation and discourse have their own keys
    c = of('do not move it, please')
    assert.deepEqual([c.clause('move').form, c.clause('move').words('auxiliary'), c.clause('move').words('negation'), c.clause('move').words('discourse')],
      ['imperative', ['do'], ['not'], ['please']])

    // a word of thanks is discourse and shares no verb
    c = of('move the box, and thanks')
    const [thanks] = c.clauses.filter(wire => wire.form === 'fragment')
    assert.deepEqual([thanks.words('discourse'), thanks.refs('ellipsis'), thanks.refs('complement')], [['thanks'], [], []])
    assert.deepEqual(c.coordinations[0].refs('conjunct'), [c.clause('move'), thanks])
    c = of('Thanks!')
    assert.deepEqual(c.wires.map(wire => [wire.type, wire.form, wire.words('discourse')]), [['clause', 'fragment', ['Thanks']]])

    // a fragment has no verb; its nominal is a complement, the word after it a modifier
    c = of('pie radius smaller')
    assert.deepEqual(c.clauses.map(wire => [wire.form, wire.words('verb'), wire.words('modifier')]), [['fragment', [], ['smaller']]])
    assert.deepEqual([c.nominal('radius').words('dependent'), c.clauses[0].refs('complement')], [['pie'], [c.nominal('radius')]])

    // a participle that describes a nominal: a nonfinite clause, tied with no marker
    c = of('a bird facing left')
    assert.deepEqual([c.clause('facing').form, c.clause('facing').words('modifier')], ['nonfinite', ['left']])
    const [tie] = c.relations
    assert.deepEqual([tie.words('marker'), tie.refs('from')[0], tie.refs('to')[0]], [[], c.nominal('bird'), c.clause('facing')])

    // two complements, no roles
    c = of('give the avatar a hat')
    assert.deepEqual(c.clause('give').refs('complement'), [c.nominal('avatar'), c.nominal('hat')])
    assert.deepEqual(c.relations, [])

    c = of('the title is too long')
    assert.deepEqual([c.clause('is').form, c.clause('is').words('modifier'), c.clause('is').refs('subject')], ['declarative', ['too', 'long'], [c.nominal('title')]])

    // a subordinator and the possessive "'s" are markers
    c = of('move it if it fits')
    assert.deepEqual([c.relation('if').refs('from')[0], c.relation('if').refs('to')[0]], [c.clause('move'), c.clause('fits')])
    assert.equal(c.clause('fits').form, 'declarative')
    c = of("point me to the Publish oval's position")
    assert.deepEqual([c.relation("'s").refs('from')[0], c.relation("'s").refs('to')[0]], [c.nominal('position'), c.nominal('oval')])
    assert.deepEqual(c.nominal('oval').words('dependent'), ['the', 'Publish'])
    assert.equal(c.relation('to').refs('to')[0], c.nominal('position'))

    // a quotation is one nominal; a hyphenated compound is one value
    c = of('add a heading called Newsletter; then create a paragraph saying "We will review the draft tomorrow."')
    assert.ok(c.nominal('We will review the draft tomorrow'))
    assert.deepEqual(c.clause('saying').refs('complement'), [c.nominal('We will review the draft tomorrow')])
    assert.deepEqual([c.clause('called').form, c.clause('called').refs('complement')], ['nonfinite', [c.nominal('Newsletter')]])
    assert.equal(c.clause('review'), undefined)
    c = of('make the x-axis label bold')
    assert.deepEqual([c.nominal('label').words('dependent'), c.clause('make').words('modifier')], [['the', 'x-axis'], ['bold']])

    // a marker before a nominal that stands alone: the nominal ends a relation from the fragment
    c = of('how about a painting')
    assert.deepEqual([c.clauses[0].form, c.clauses[0].words('modifier'), c.clauses[0].refs('complement')], ['fragment', ['how'], []])
    assert.deepEqual([c.relation('about').refs('from')[0], c.relation('about').refs('to')[0]], [c.clauses[0], c.nominal('painting')])

    // Rule 1: repeated words are claimed in the order of the message
    const text = 'put the box on the box'
    const {placements} = validateSyntax(text, results.get(text).candidates[0].sop)
    const heads = placements.filter(place => place.key === 'head').map(place => place.first)
    assert.deepEqual(heads, [2, 5])
    c = of(text)
    assert.equal(c.clause('put').refs('complement')[0], c.nominals[0])
    assert.equal(c.relation('on').refs('to')[0], c.nominals[1])
  })
}

// ---------------------------------------------------------------------------------------------
// What each strategy adds to the plain parse
// ---------------------------------------------------------------------------------------------

test('neural-dependencies writes the parse as it stands; spacy-direct sets run-on clauses side by side', async () => {
  const statement = 'the gaps are uneven, distribute each round node from top to bottom'
  const sequence = 'add a heading called Newsletter; then create a paragraph saying "We will review the draft tomorrow."'
  const plain = await circuits(neuralDependencies, [statement, sequence])
  const direct = await circuits(spacyDirect, [statement, sequence])
  const between = (circuit, a, b) => circuit.relations.filter(wire => wire.refs('from')[0] === circuit.clause(a) && wire.refs('to')[0] === circuit.clause(b))

  // the parser hangs the statement on the command as its complement clause
  let c = read(plain.get(statement).candidates[0].sop)
  assert.equal(between(c, 'distribute', 'are').length, 1)
  assert.deepEqual(c.coordinations, [])
  // a statement before a command is no complement of it: two clauses side by side
  c = read(direct.get(statement).candidates[0].sop)
  assert.equal(between(c, 'distribute', 'are').length, 0)
  assert.deepEqual(c.coordinations.map(wire => wire.refs('conjunct')), [[c.clause('are'), c.clause('distribute')]])
  assert.deepEqual([c.clause('are').form, c.clause('distribute').form], ['declarative', 'imperative'])

  // across a semicolon: the plain parse subordinates, the corrected one coordinates, and "then" joins
  c = read(plain.get(sequence).candidates[0].sop)
  assert.equal(between(c, 'create', 'add').length, 1)
  assert.deepEqual(c.clause('create').words('modifier'), ['then'])
  c = read(direct.get(sequence).candidates[0].sop)
  assert.equal(between(c, 'create', 'add').length, 0)
  assert.deepEqual(c.coordinations.map(wire => [wire.refs('conjunct'), wire.words('conjunction')]), [[[c.clause('add'), c.clause('create')], ['then']]])
  assert.deepEqual(c.clause('create').words('modifier'), [])
})

test('the form of a clause: embedded questions, question tags, names that end in a question mark', async () => {
  const texts = ['tell me where Verify is in the row', 'same session, next ask: Who leads on profit, and how far clear is it?',
    'how about three birds in a row along the fence all facing left? — right where the scene needs it',
    'drop in a library, would you', 'put a plane on the board, would you', 'one more thing: quick check — is anything overlapping the house?',
    'I would like the avatar back to default, so please reset it and remember that for the next session.',
    'make Valid? a rounded rectangle', 'add a circle called Retry and connect Valid? to it']
  const results = await circuits(spacyDirect, texts)
  const of = text => read(results.get(text).candidates[0].sop)

  // an embedded question keeps the order of a statement: no question; one that a question mark closes after a colon asks
  let c = of('tell me where Verify is in the row')
  assert.deepEqual([c.clause('tell').form, c.clause('is').form], ['imperative', 'declarative'])
  c = of('same session, next ask: Who leads on profit, and how far clear is it?')
  assert.deepEqual([c.clause('leads').form, c.clause('is').form], ['interrogative', 'interrogative'])
  // a question word with the order of a statement and no question mark opens a relative clause; "right" grades "where"
  c = of('how about three birds in a row along the fence all facing left? — right where the scene needs it')
  assert.deepEqual([c.clause('needs').form, c.clause('needs').words('modifier')], ['declarative', ['right', 'where']])

  // a question tag is an elliptical question set beside the command, also when the parser hung its auxiliary on the verb
  for (const text of ['drop in a library, would you', 'put a plane on the board, would you']) {
    c = of(text)
    assert.deepEqual([c.clause('would').form, c.clause('would').refs('subject'), c.coordinations[0].refs('conjunct')],
      ['interrogative', [c.nominal('you')], [c.clauses[0], c.clause('would')]], text)
    assert.deepEqual(c.clauses[0].words('auxiliary'), [], text)
  }
  // an auxiliary before its subject makes a question, which only a main clause can be
  c = of('one more thing: quick check — is anything overlapping the house?')
  assert.deepEqual([c.clause('overlapping').form, c.clause('overlapping').words('auxiliary')], ['interrogative', ['is']])

  // "please" before a joined verb: a command of its own, not a second verb of "would like"
  c = of('I would like the avatar back to default, so please reset it and remember that for the next session.')
  assert.deepEqual([c.clause('like').form, c.clause('reset').form, c.clause('remember').form], ['declarative', 'imperative', 'imperative'])

  // a question mark between a capitalised word and words that go on is part of a name: the command stays a command
  c = of('make Valid? a rounded rectangle')
  assert.deepEqual([c.clause('make').form, c.clause('make').refs('complement')], ['imperative', [c.nominal('Valid'), c.nominal('rectangle')]])
  c = of('add a circle called Retry and connect Valid? to it')
  assert.deepEqual([c.clause('add').form, c.clause('connect').form, c.clause('connect').refs('complement')], ['imperative', 'imperative', [c.nominal('Valid')]])
})

test('word classes: a command opens with its verb, a capitalised word inside a sentence is a name', async () => {
  const texts = ['dissolve Process', 'update a pipe neck tiny', 'set r1 width 180 height 90', 'undo the last document edit', 'clear everything',
    'connect a link from Start to Review', 'group an object Plan Backup', 'add a person Hub Core',
    'put a level 2 heading Results after Chapter and name the object Findings']
  const results = await circuits(spacyDirect, texts)
  const of = text => read(results.get(text).candidates[0].sop)

  // the first word of a message with no verb, before a name, a determiner or a pronoun, is the verb
  let c = of('dissolve Process')
  assert.deepEqual([c.clause('dissolve').form, c.clause('dissolve').refs('complement')], ['imperative', [c.nominal('Process')]])
  c = of('clear everything')
  assert.deepEqual([c.clause('clear').form, c.clause('clear').refs('complement')], ['imperative', [c.nominal('everything')]])
  // and an adjective after the nouns is said of them: the last noun is the head
  c = of('update a pipe neck tiny')
  assert.deepEqual([c.clause('update').words('modifier'), c.clause('update').refs('complement'), c.nominal('neck').words('dependent')],
    [['tiny'], [c.nominal('neck')], ['a', 'pipe']])
  // a word tagged as a base form of a verb opens a command whatever follows it
  c = of('set r1 width 180 height 90')
  assert.deepEqual([c.clause('set').form, c.clause('set').refs('complement')], ['imperative', [c.nominal('width')]])
  // a bare noun right after the object belongs to it
  c = of('undo the last document edit')
  assert.deepEqual([c.clause('undo').refs('complement'), c.nominal('edit').words('dependent')], [[c.nominal('edit')], ['the', 'last', 'document']])

  // a capitalised verb form inside a sentence is a name
  c = of('connect a link from Start to Review')
  assert.deepEqual(c.clauses.map(wire => wire.words('verb')), [['connect']])
  assert.deepEqual([c.relation('from').refs('to')[0], c.relation('to').refs('to')[0]], [c.nominal('Start'), c.nominal('Review')])

  // a name right after a noun that brings in a new thing names it (Rule 5.5); after a known thing it is what the verb gives it
  c = of('add a person Hub Core')
  assert.deepEqual(c.clause('add').refs('complement'), [c.nominal('person')])
  assert.deepEqual(c.relations.map(wire => [wire.words('marker'), wire.refs('from')[0], wire.refs('to')[0]]), [[[], c.nominal('person'), c.nominal('Core')]])
  c = of('group an object Plan Backup')
  assert.deepEqual([c.clause('group').refs('complement'), c.relations[0].refs('from')[0], c.relations[0].refs('to')[0]], [[c.nominal('object')], c.nominal('object'), c.nominal('Backup')])
  c = of('put a level 2 heading Results after Chapter and name the object Findings')
  assert.deepEqual(c.clause('name').refs('complement'), [c.nominal('object'), c.nominal('Findings')])
})

test('nominals and relations: numbers, "left of", "let\'s", "else", "from now on", nouns side by side', async () => {
  const texts = ['our rectangle 220 by 140', 'a boy in the blue jacket just left of the woman in the green dress', 'Make a gazelle left of the hill.',
    "let's go linear on y axis scale", 'place both cats at the left side, keeping everything else where it is', 'From now on, data labels on.',
    'the marker borders on Revenue trend should be thicker. flip the x axis']
  const results = await circuits(spacyDirect, texts)
  const of = text => read(results.get(text).candidates[0].sop)

  // a preposition between two numbers marks a relation from the first to the second
  let c = of('our rectangle 220 by 140')
  assert.deepEqual([c.relation('by').refs('from')[0], c.relation('by').refs('to')[0]], [c.nominal('220'), c.nominal('140')])
  // "of" goes with "left", never with the thing placed; "left" before "of" is no participle
  c = of('a boy in the blue jacket just left of the woman in the green dress')
  assert.deepEqual([c.clauses[0].words('modifier'), c.relation('of').refs('from')[0], c.relation('of').refs('to')[0]], [['just', 'left'], c.clauses[0], c.nominal('woman')])
  c = of('Make a gazelle left of the hill.')
  assert.deepEqual([c.clauses.length, c.clause('Make').words('modifier'), c.relation('of').refs('from')[0]], [1, ['left'], c.clause('Make')])
  // the "'s" of "let's" is the object of "let", not the subject of the verb after it
  c = of("let's go linear on y axis scale")
  assert.deepEqual([c.clause('let').refs('complement'), c.clause('go').refs('subject')], [[c.nominal("'s")], []])
  // "else" belongs to its pronoun
  c = of('place both cats at the left side, keeping everything else where it is')
  assert.deepEqual([c.nominal('everything').words('dependent'), c.clause('keeping').words('modifier')], [['else'], []])
  // "from now on": "from" governs "now", "on" grades it; set before the nominal by a comma, the phrase belongs to the clause
  c = of('From now on, data labels on.')
  assert.deepEqual([c.relation('From').refs('from')[0], c.relation('From').refs('to')[0], c.clauses[0].words('modifier')], [c.clauses[0], c.nominal('now'), ['on', 'on']])
  // a noun the parser made the subject of the noun after it forms one nominal with it
  c = of('the marker borders on Revenue trend should be thicker. flip the x axis')
  assert.deepEqual([c.nominal('borders').words('dependent'), c.clause('be').refs('subject')], [['the', 'marker'], [c.nominal('borders')]])
})

test('clause boundaries: "then", adverbs set off by a comma, a comma after a subject, a word that grades a subordinator', async () => {
  const texts = ['place one bird on the top of the tree, then one kite on top of it, then one cloud on top of the kite',
    'instead, a yellow column the same size between the two blue columns', 'mirror the boat in both directions then blur the waterline a little',
    'make it the next day exactly as i said',
    'a little black cat curled up near the bench, then make the shiny parts of the surfboard by the water clear pale blue and keep the rest of the object as it is, and the shape of the object does not change']
  const results = await circuits(spacyDirect, texts)
  const of = text => read(results.get(text).candidates[0].sop)

  // "then" before a group of words with no verb joins it to what stands before; it is no word of the nominal
  let c = of('place one bird on the top of the tree, then one kite on top of it, then one cloud on top of the kite')
  assert.deepEqual([c.coordinations[0].words('conjunction'), c.nominal('kite').words('dependent'), c.nominal('cloud').words('dependent')], [['then', 'then'], ['one'], ['one']])
  // an adverb set off by a comma before a nominal modifies the clause
  c = of('instead, a yellow column the same size between the two blue columns')
  assert.deepEqual([c.clauses[0].words('modifier'), c.nominal('column').words('dependent')], [['instead'], ['a', 'yellow']])
  // "then" opens the clause it stands before, also with no comma
  c = of('mirror the boat in both directions then blur the waterline a little')
  assert.deepEqual([c.coordinations[0].refs('conjunct'), c.coordinations[0].words('conjunction'), c.clause('mirror').words('modifier')],
    [[c.clause('mirror'), c.clause('blur')], ['then'], []])
  // a word that grades the subordinator modifies the clause the relation starts at
  c = of('make it the next day exactly as i said')
  assert.deepEqual([c.clause('make').words('modifier'), c.clause('said').words('modifier'), c.relation('as').refs('from')[0]], [['exactly'], [], c.clause('make')])
  // no comma stands between a subject and its verb: the cat is a group of words of its own, and "make" commands
  c = of('a little black cat curled up near the bench, then make the shiny parts of the surfboard by the water clear pale blue and keep the rest of the object as it is, and the shape of the object does not change')
  assert.deepEqual([c.clause('make').form, c.clause('make').refs('subject'), c.clause('keep').form], ['imperative', [], 'imperative'])
})

test('second round: words of the clause, names after nouns, "left", restarts, shared verbs, "so", "not"', async () => {
  const texts = ['bring the deleted shape back into the row and exchange it with the figure immediately to its right', 'turn the garden path slick and reflective',
    'Could you make Cake orange. Thanks!', 'change a circle Follow-up', 'the big cat: face left', 'run the boy in the blue coat and yellow cap left one place, same as the other',
    'add a cirrcle Rough Take 2', 'position one doughnut Second Pass', 'Let us what colour is bubbles?. That would help.',
    'I need you to what values does League show?. I appreciate it.', 'add a small crown to the girl, next, a red cape over her dress, and finish with white gloves under the cape',
    'place one bird on the top of the tree, then one kite on top of it, then one cloud on top of the kite',
    'put the red barn away from the road, so nothing blocks the lane.', 'it is a hierarchy, so lay out the diagram horizoontally', 'change a raiised eyebrow pink',
    'just take the trees out but keep the ones beside the house', 'how about small marker size?', 'please to place flow along the curve',
    'o — the cloud in the sky is small, not big', 'no — have the blue-dress woman take the next turn, not the man in the green jacket']
  const results = await circuits(spacyDirect, texts)
  const of = text => read(results.get(text).candidates[0].sop)

  // a word that grades a marker modifies the clause, also when the relation starts at a nominal
  let c = of('bring the deleted shape back into the row and exchange it with the figure immediately to its right')
  assert.deepEqual([c.clause('exchange').words('modifier'), c.nominal('figure').words('dependent')], [['immediately'], ['the']])
  // a conjunction between two words that modify a clause is a word of discourse
  c = of('turn the garden path slick and reflective')
  assert.deepEqual([c.clause('turn').words('modifier'), c.clause('turn').words('discourse')], [['slick', 'reflective'], ['and']])
  // a noun with no verb hung on a verb as its clause: the noun before it is the object, the last word what it is made
  c = of('Could you make Cake orange. Thanks!')
  assert.deepEqual([c.clause('make').words('modifier'), c.clause('make').refs('complement')], [['orange'], [c.nominal('Cake')]])
  // a hyphenated compound is no particle; capitalised, it names the noun before it
  c = of('change a circle Follow-up')
  assert.deepEqual([c.relations[0].refs('from')[0], c.relations[0].refs('to')[0]], [c.nominal('circle'), c.nominal('Follow-up')])
  // "left" after a verb of motion the tagger read as a noun is the direction
  c = of('the big cat: face left')
  assert.deepEqual([c.clause('face').form, c.clause('face').words('modifier')], ['imperative', ['left']])
  c = of('run the boy in the blue coat and yellow cap left one place, same as the other')
  assert.deepEqual([c.clause('run').form, c.clause('run').refs('complement')[0], c.clauses.length], ['imperative', c.nominal('boy'), 1])
  // a small-lettered word between a determiner and a name is the noun the name names
  c = of('add a cirrcle Rough Take 2')
  assert.deepEqual([c.clause('add').refs('complement'), c.nominal('cirrcle').words('dependent'), c.relations[0].refs('to')[0]], [[c.nominal('cirrcle')], ['a'], c.nominal('Take')])
  // a numeral written as a word before a noun opens the nominal: the word before it is the verb
  c = of('position one doughnut Second Pass')
  assert.deepEqual([c.clause('position').refs('complement'), c.nominal('doughnut').words('dependent')], [[c.nominal('doughnut')], ['one']])
  // a question word after a pronoun or "to" starts a question of its own
  c = of('Let us what colour is bubbles?. That would help.')
  assert.deepEqual([c.clause('Let').form, c.clause('is').form, c.coordinations[0].refs('conjunct')], ['imperative', 'interrogative', [c.clause('Let'), c.clause('is')]])
  c = of('I need you to what values does League show?. I appreciate it.')
  assert.deepEqual([c.clause('need').form, c.clause('show').form, c.relation('to').refs('from')[0], c.relation('to').refs('to')[0]],
    ['declarative', 'interrogative', c.clause('need'), c.clause('show')])
  // a group of words opened by a linking word of sequence after a verb shares that verb
  c = of('add a small crown to the girl, next, a red cape over her dress, and finish with white gloves under the cape')
  assert.deepEqual(c.clauses.find(wire => wire.refs('complement')[0] === c.nominal('cape')).refs('ellipsis'), [c.clause('add')])
  c = of('place one bird on the top of the tree, then one kite on top of it, then one cloud on top of the kite')
  assert.deepEqual(c.clauses.filter(wire => wire.form === 'fragment').map(wire => wire.refs('ellipsis')), [[c.clause('place')], [c.clause('place')]])
  // "so" after a comma joins its clause to the one before
  c = of('put the red barn away from the road, so nothing blocks the lane.')
  assert.deepEqual([c.relation('so').refs('from')[0], c.relation('so').refs('to')[0], c.clause('blocks').words('modifier')], [c.clause('put'), c.clause('blocks'), []])
  c = of('it is a hierarchy, so lay out the diagram horizoontally')
  assert.deepEqual([c.coordinations[0].words('conjunction'), c.clause('lay').form], [['so'], 'imperative'])
  // a bare singular noun ending the clause after the object is what the object is made
  c = of('change a raiised eyebrow pink')
  assert.deepEqual([c.clause('change').words('modifier'), c.nominals.length], [['pink'], 1])
  // a preposition that governs an object marks a relation, whatever relation it was hung by
  c = of('just take the trees out but keep the ones beside the house')
  assert.deepEqual([c.relation('beside').refs('from')[0], c.relation('beside').refs('to')[0]], [c.clause('keep'), c.nominal('house')])
  c = of('how about small marker size?')
  assert.deepEqual([c.clauses[0].words('modifier'), c.relation('about').refs('to')[0]], [['how'], c.nominal('size')])
  // "to" after nothing but a word said to the listener ties the infinitive to that word
  c = of('please to place flow along the curve')
  assert.deepEqual([c.clauses[0].words('discourse'), c.relation('to').refs('to')[0], c.clause('place').form], [['please'], c.clause('place'), 'nonfinite'])
  // a word set after a comma with "not" is a fragment that shares the verb, with its own negation
  c = of('o — the cloud in the sky is small, not big')
  assert.deepEqual([c.clause('is').words('modifier'), c.clauses.find(wire => wire.form === 'fragment').words('negation'), c.clauses.find(wire => wire.form === 'fragment').refs('ellipsis')],
    [['small'], ['not'], [c.clause('is')]])
  c = of('no — have the blue-dress woman take the next turn, not the man in the green jacket')
  const contrast = c.clauses.find(wire => wire.refs('complement')[0] === c.nominal('man'))
  assert.deepEqual([contrast.words('negation'), contrast.refs('ellipsis'), c.nominal('man').words('dependent')], [['not'], [c.clause('take')], ['the']])
})

test('third round: "so", stranded prepositions, list items, learned command openers, names, shared forms, absolute "with"', async () => {
  const texts = ['I walked the team through Budget split this morning; nobody argued with the data, only with how it reads at a glance, so as a first pass rename the rent series Data Size, then we revisit next week, could you also show the percentages',
    'what is link e4 between?', 'and now drag it up and to the left of Check because that is the order the two steps happen in when the diagram is read aloud',
    'draw four large yellow sandboxes in the corners, four small kids facing right right in the sandbox, a medium coach standing toward the middle, and a medium brown dog with a happy face next to the coach',
    'to start, a red kite high in the sky, then in front of the tree a large boy facing left', 'show me a bakery at dawn: a dough ball, a rolling pin, two sacks, a mouse, and a baker',
    'plot sales by month, lines split out by category as a line chart', 'flip', 'chart title in the top left corner. legend on the right',
    'draw an arrow from Draft to Review and label it retry', 'change a heaart head yellow big', 'change a teaar cheek purple big',
    'I need you to what values does Photosynthesis show?. I appreciate it.',
    "while you're there, I'd like the title start with a capital letter on the orders chart plus how about x axis on top?", 'make one dotted Status Summary Follow-up',
    'picture the man jumping in the air, and push the whole page into heavy comic book style', 'keep the bottom numbers powered, and go for y numbers even, starting at 0 on the orders chart',
    'please to draw three layers with a legend and a callout, with the legend in the corner and the callout pointing at the front layer',
    'next, put a medium red swing just next to the tree, above it, three small red balloons, a small girl with a smiling face right on the swing, and a small boy standing just next to the swing together',
    'cheeks — add a sideburns, please', 'excuse me — the missing piece: tick marks every five on the department chart',
    'now a second wooden boat in the same little pond, among the reeds on the quiet side of the water.', 'can you add two kites side by side in the sky facing right? — right where the scene needs it',
    'draw a woman with her arms outstretched', 'the best spot for a little bench is within the fence, on the lawn with the gate stlil reachable.',
    'Make a scatter plot of ad spend against revenue, with campaign as the legend for the summary slide, and put the legend on the right',
    'a jungle clearing at noon with a large green snake right under the tree, two small green frogs right on the rock, a medium brown owl on the tree, and a medium explorer kneeling facing left right next to the rock, and keep the animals in the foreground from now on']
  const results = await circuits(spacyDirect, texts)
  const of = text => read(results.get(text).candidates[0].sop)

  // "so" opens the clause right after it, whatever later verb the parser hung it on
  let c = of(texts[0])
  assert.deepEqual([c.relation('so').refs('from')[0], c.relation('so').refs('to')[0], c.coordinations[0].refs('conjunct').includes(c.clause('rename'))],
    [c.clause('argued'), c.clause('rename'), false])
  // a preposition left at the end of a question or a relative clause governs what the clause is about
  c = of('what is link e4 between?')
  assert.deepEqual([c.relation('between').refs('to')[0], c.clause('is').words('modifier')], [c.nominal('what'), []])
  c = of(texts[2])
  assert.deepEqual([c.relation('in').refs('from')[0], c.relation('in').refs('to')[0]], [c.clause('happen'), c.nominal('order')])
  // a new thing after a comma and a new thing is the next item of a list; after a colon it says what the thing is made of
  c = of(texts[3])
  assert.deepEqual(c.clause('draw').refs('complement')[0].refs('conjunct'), [c.nominal('sandboxes'), c.nominal('kids'), c.nominal('coach'), c.nominal('dog')])
  c = of(texts[4])
  assert.deepEqual([c.coordinations[0].refs('conjunct'), c.coordinations[0].words('conjunction'), c.nominal('boy').words('dependent')],
    [[c.nominal('kite'), c.nominal('boy')], ['then'], ['a', 'large']])
  c = of(texts[5])
  assert.deepEqual([c.clause('show').refs('complement'), c.relations.some(wire => !wire.words('marker').length && wire.refs('from')[0] === c.nominal('bakery'))],
    [[c.nominal('me'), c.nominal('bakery')], true])
  // a word that the raw text shows opening commands is the verb before a noun, or alone; not inside a nominal pair the text writes after a determiner
  c = of(texts[6])
  assert.deepEqual([c.clause('plot').form, c.clause('plot').refs('complement')], ['imperative', [c.nominal('sales')]])
  assert.equal(of('flip').clause('flip').form, 'imperative')
  c = of(texts[8])
  assert.deepEqual([c.clauses.map(wire => wire.form), c.nominal('title').words('dependent')], [['fragment', 'fragment'], ['chart']])
  // the "to" of an infinitive alone makes no verb of a capitalised word
  c = of(texts[9])
  assert.deepEqual([c.relation('to').refs('to')[0], c.clauses.length], [c.nominal('Review'), 2])
  // an adjective after the nominal is said of it; a word between a determiner and its noun is a word of the nominal
  c = of('change a heaart head yellow big')
  assert.deepEqual([c.clause('change').words('modifier'), c.nominals.length], [['yellow', 'big'], 1])
  c = of('change a teaar cheek purple big')
  assert.deepEqual([c.nominal('cheek').words('dependent'), c.nominals.length], [['a', 'teaar'], 1])
  // what the parser hung on "to" before a restarted question is a word of that question
  c = of(texts[12])
  assert.deepEqual([c.clause('show').refs('complement'), c.clause('need').refs('complement')], [[c.nominal('values')], [c.nominal('you')]])
  // a conjunct with its own question word asks by itself: the question mark is its own, and it borrows no verb
  c = of(texts[13])
  assert.deepEqual([c.clause('like').form, c.clauses.find(wire => wire.form === 'fragment').refs('ellipsis')], ['declarative', []])
  // a numeral object with an adjective counts the nominal after it
  assert.deepEqual(of(texts[14]).nominal('Follow-up').words('dependent'), ['one', 'dotted', 'Status', 'Summary'])
  // joined verbs share their form: a base form joined to a participle is a command beside the command above
  c = of(texts[15])
  assert.deepEqual([c.coordinations[0].refs('conjunct'), c.clause('jumping').form], [[c.clause('picture'), c.clause('push')], 'nonfinite'])
  c = of(texts[16])
  assert.deepEqual([c.coordinations[0].refs('conjunct'), c.relations.some(wire => wire.refs('from')[0] === c.clause('go') && wire.refs('to')[0] === c.clause('starting'))],
    [[c.clause('keep'), c.clause('go')], true])
  // like joins like: a participle with a subject joined to a noun joins its subject
  c = of(texts[17])
  assert.deepEqual([c.coordinations[1].refs('conjunct'), c.coordinations.some(wire => wire.refs('conjunct').includes(c.clause('pointing')))],
    [[c.nominals.find(wire => wire.words('head')[0] === 'legend' && wire.words('dependent')[0] === 'the'), c.nominals.find(wire => wire.words('head')[0] === 'callout' && wire.words('dependent')[0] === 'the')], false])
  // a group of words opened by a phrase with a marker before its nominal shares the verb
  c = of(texts[18])
  assert.deepEqual(c.clauses.find(wire => wire.form === 'fragment').refs('ellipsis'), [c.clause('put')])
  // a semicolon, colon or dash ends a clause for its nominals too
  c = of(texts[19])
  assert.deepEqual([c.clause('add').words('modifier'), c.clauses.find(wire => wire.form === 'fragment').refs('complement')], [[], [c.nominal('cheeks')]])
  c = of(texts[20])
  assert.deepEqual(c.clause('excuse').refs('complement'), [c.nominal('me')])
  // an adverb before the determiner of a message of no verb, or an interjection hung as an adverb, says how or when
  c = of(texts[21])
  assert.deepEqual([c.clauses[0].words('modifier'), c.nominal('boat').words('dependent')], [['now'], ['a', 'second', 'wooden']])
  assert.deepEqual(of(texts[22]).clause('facing').words('modifier'), ['right'])
  // a preposition governs the nominal of an absolute construction; a subordinated group of no verb is a clause of its own
  c = of(texts[23])
  assert.deepEqual([c.relation('with').refs('to')[0], c.nominal('arms').words('dependent'), c.clause('draw').refs('complement')], [c.nominal('arms'), ['her', 'outstretched'], [c.nominal('woman')]])
  c = of(texts[24])
  assert.deepEqual([c.relation('with').refs('to')[0].form, c.clause('is').words('discourse')], ['fragment', []])
  c = of(texts[25])
  assert.deepEqual([c.relation('with').refs('to')[0], c.relation('as').refs('from')[0], c.clause('Make').words('modifier')], [c.nominal('campaign'), c.nominal('campaign'), []])
  // a clause the parser made a second root, opened by a conjunction after a comma, is joined to the root before it
  c = of(texts[26])
  assert.deepEqual([c.coordinations.find(wire => wire.refs('conjunct').includes(c.clause('keep'))).words('conjunction'), c.clause('keep').words('discourse')], [['and'], []])
})

test('fourth round: describing words, "do" and "have" as verbs, particles, places before list items, participles, learned nouns, subordinated conjuncts', async () => {
  const market = 'on the market street, at noon, a small woman standing facing right right behind the stall, under the stall, a medium white duck, right next to the stall, a small girl, and right on the stall, three small brown breads, and have the people stay in the foreground from here on'
  const turn = 'turn the man by the house to face left — with everything else left where it is — over on our little canvas'
  const diamond = 'add a diamond labelled Crop cycle; then link Crop cycle to sow; then make Crop cycle red.'
  const woman = 'the woman in the green scarf needs to face right, and a tall girl by the tree facing right — with everything else left where it is'
  const borders = 'can you make the line thinner? and I want the marker borders thicker on the revenue trend'
  const tick = 'make the bottom tick numbers 0 to 10 from the left plus do the error bar cap size small on the sales chart'
  const cat = 'a little cat near the bench, then send the whole line one spot right, so every gap stays the same, no other change to the scene'
  const book = 'book Room 2 for Planning on 2026-12-13 from 13:00 UTC for 15 minutes.'
  const chart = 'Chart revenue against order date for 2019 to 2024 in monthly buckets, coloured by category in a line chart'
  const brick = "brick walls for the house — and the shed walls too, if it's easy"
  const kid = 'do you see a kid facing the tree? and how many kids are there? — exactly where the picture needs it'
  const forget = 'Forget the old value and use a pastel palette, because the first one looked wrong.'
  const steps = 'how many steps until the row is back in the original order, and how many moves until it is back in its starting order?'
  const across = 'I want a horizontal bar chart, revenue running across and region down the side, a repeat for the second section'
  const please = 'Please make the legend moved right the standard choice, because changing it every time takes too long.'
  const texts = ['tint the Intro node orange', 'add a calendar with label Review and colour teal', 'do the callout arrow head bigger on the revenue trend',
    'do that swap again but the other way round', 'have everything come out as a proper comic book front page', 'Have the legend switched on.', please,
    'drop in a navy box under Load, please', 'drop in a restaurant, would you', market, turn, diamond, woman, borders, tick, cat, book, chart,
    'node Intro to 260, 240', 'rectangle around the Alpha branch, please', brick, kid, forget, steps, across]
  const results = await circuits(spacyDirect, texts)
  const of = text => read(results.get(text).candidates[0].sop)

  // a word the raw text shows to be an adjective, read as the head of the nouns before it, is said of them
  let c = of('tint the Intro node orange')
  assert.deepEqual([c.clause('tint').words('modifier'), c.nominal('node').words('dependent')], [['orange'], ['the', 'Intro']])
  assert.deepEqual(of('add a calendar with label Review and colour teal').nominal('colour').words('dependent'), ['teal'])
  // "do" or "have" before a singular subject is no auxiliary of it: the main verb of a command
  c = of('do the callout arrow head bigger on the revenue trend')
  assert.deepEqual([c.clause('do').form, c.clause('do').refs('complement'), c.clause('do').words('modifier')], ['imperative', [c.nominal('head')], ['bigger']])
  c = of('do that swap again but the other way round')
  assert.deepEqual([c.clause('do').refs('complement')[0], c.nominal('swap').words('dependent')], [c.nominal('swap'), ['that']])
  c = of('have everything come out as a proper comic book front page')
  assert.deepEqual([c.clause('have').form, c.clause('come').refs('subject'), c.relations.some(wire => wire.refs('from')[0] === c.clause('have') && wire.refs('to')[0] === c.clause('come'))],
    ['imperative', [c.nominal('everything')], true])
  c = of('Have the legend switched on.')
  assert.deepEqual([c.clause('Have').form, c.clause('switched').form], ['imperative', 'nonfinite'])
  // a word outside the closed class of auxiliaries is no auxiliary
  c = of(please)
  assert.deepEqual([c.clause('make').words('discourse'), c.clause('make').words('auxiliary')], [['Please'], []])
  // "in" before a new thing, after the verb of a command with no object, is its particle
  c = of('drop in a navy box under Load, please')
  assert.deepEqual([c.clause('drop').words('modifier'), c.clause('drop').refs('complement'), c.relation('in')], [['in'], [c.nominal('box')], undefined])
  assert.deepEqual(of('drop in a restaurant, would you').clause('drop').words('modifier'), ['in'])
  // a place phrase between commas before the next item of a list places that item
  c = of(market)
  assert.deepEqual([c.relation('under').refs('from')[0], c.relation('next to').refs('from')[0]], [c.nominal('duck'), c.nominal('girl')])
  // the clause of a participle is written: "to face left", "everything else left where it is", "a diamond labelled Crop cycle"
  c = of(turn)
  assert.deepEqual([c.relation('to').refs('to')[0], c.clause('face').words('modifier'), c.clause('left').refs('subject')], [c.clause('face'), ['left'], [c.nominal('everything')]])
  c = of(diamond)
  assert.deepEqual([c.clause('labelled').refs('complement'), c.relations.some(wire => wire.refs('from')[0] === c.nominal('diamond') && wire.refs('to')[0] === c.clause('labelled'))],
    [[c.nominal('cycle')], true])
  c = of(woman)
  assert.deepEqual([c.relation('with').refs('to')[0], c.nominal('everything').words('dependent')], [c.clause('left'), ['else']])
  // a word the raw text shows to be a noun, read as a verb after the nouns of a nominal, ends that nominal
  c = of(borders)
  assert.deepEqual([c.clause('want').refs('complement'), c.nominal('borders').words('dependent'), c.clause('want').words('modifier')], [[c.nominal('borders')], ['the', 'marker'], ['thicker']])
  c = of(tick)
  assert.deepEqual([c.clause('make').refs('complement'), c.nominal('numbers').words('dependent'), c.clause('tick')], [[c.nominal('numbers')], ['the', 'bottom', 'tick'], undefined])
  // a nominal that brings in a new thing before ", then" stands apart from the clause after it
  c = of(cat)
  assert.deepEqual([c.clause('send').refs('complement').includes(c.nominal('cat')), c.coordinations[0].words('conjunction')], [false, ['then']])
  // a capitalised participle in the place of a nominal is a name; a learned command opener keeps the capital of its sentence
  assert.equal(of(book).clause('book').form, 'imperative')
  c = of(chart)
  assert.deepEqual([c.clause('Chart').form, c.clause('Chart').refs('complement')], ['imperative', [c.nominal('revenue')]])
  // a word the raw text shows to open no commands is a noun; a second number after a comma is paired with the first
  c = of('rectangle around the Alpha branch, please')
  assert.deepEqual([c.clauses[0].form, c.relation('around').refs('from')[0]], ['fragment', c.nominal('rectangle')])
  c = of('node Intro to 260, 240')
  assert.deepEqual([c.clauses[0].form, c.relations.some(wire => !wire.words('marker').length && wire.refs('from')[0] === c.nominal('260') && wire.refs('to')[0] === c.nominal('240'))], ['fragment', true])
  // a joined clause opened by a subordinator or a relative word depends on the clause before it
  c = of(brick)
  assert.deepEqual([c.relation('if').refs('to')[0], c.coordinations.length], [c.clause("'s"), 1])
  c = of(kid)
  assert.deepEqual([c.relation('where').refs('from')[0], c.coordinations[0].refs('conjunct'), c.clause('are').words('modifier')], [c.clause('are'), [c.clause('see'), c.clause('are')], ['exactly']])
  c = of(forget)
  assert.deepEqual([c.relation('because').refs('from')[0], c.coordinations[0].words('conjunction')], [c.clause('use'), ['and']])
  // joined nominals of a group of words with no verb keep the adverbial clauses that follow them
  c = of(steps)
  assert.deepEqual(c.relations.filter(wire => wire.words('marker')[0] === 'until').map(wire => wire.refs('from')[0]), [c.nominal('steps'), c.nominal('moves')])
  // a preposition with a conjunction after it governs nothing
  c = of(across)
  assert.deepEqual([c.clause('running').words('modifier'), c.relation('across'), c.coordinations.find(wire => wire.words('conjunction')[0] === 'and').refs('conjunct')],
    [['across'], undefined, [c.nominal('revenue'), c.nominal('region')]])
})

test('fifth round: nouns in -ing, compounds, "no …", "of" after a part, names after nouns, words of address, lists, numbers', async () => {
  const bird = 'a little bird up in the top right, then the woman in the red dress exits the scene, no other change — exactly like it was before'
  const cat = 'a little cat near the bench, then send the whole line one spot right, so every gap stays the same, no other change to the scene'
  const market = 'on the market street, at noon, a small woman standing facing right right behind the stall, under the stall, a medium white duck, right next to the stall, a small girl, and right on the stall, three small brown breads, and have the people stay in the foreground from here on'
  const whatIf = 'what if we put a tall tree in front of the stone house, so it is the first thing seen from the road.'
  const histogram = 'build a histogram of the orders by quantity with the values shown on the bars and grids on, as the one chart everyone waits for, then after that, I need the order tally for three or more units'
  const texts = ['make the vertical dashed lines at every y tick', 'actually, it looks odd on the left, so align the chapter heading to the right',
    'turn the bold in the Introduction heading off', 'change the avatar kind to alien', 'the marker borders on Revenue trend should be thicker. flip the x axis',
    bird, cat, 'hey — remove all but three of them of those five clouds', whatIf, 'markers little diamonds',
    'The next thing is to label the x axis Month on the bar chart.', 'add a pie Second Main Intro', 'add a hert Take 2 260', "Let's histogram wait time.",
    'add a box close beside Slide', 'point the girl right and have her sit with her legs out on the grass', 'for the map, add a scale bar under the figure, marked 0 to 10 m',
    'caviar, please', 'do the callout arrows curved on the revenue trend', 'the missing piece: bar gap small on the sales chart. legend on the right',
    'add a paragraph saying Welcome', 'change Weekly review on Monday at 10:00 and the notes to bring the slides', "I'd like a box and three circles in a row",
    'rewrite the paragraph as Thank you for your patience.', 'Hello in the first paragraph, bold', market, histogram, 'Hey, make Tractor 2 62 pixels wide.',
    'how about a poodle instead? — go on']
  const results = await circuits(spacyDirect, texts)
  const of = text => read(results.get(text).candidates[0].sop)

  // a noun the raw text shows to be one (in -ing with a plural), read as a verb after the words of a nominal, ends that nominal
  let c = of('make the vertical dashed lines at every y tick')
  assert.deepEqual([c.clauses.length, c.clause('make').refs('complement'), c.nominal('tick').words('dependent')], [1, [c.nominal('lines')], ['every', 'y']])
  assert.deepEqual(of('actually, it looks odd on the left, so align the chapter heading to the right').clause('align').refs('complement')[0].words('head'), ['heading'])
  c = of('turn the bold in the Introduction heading off')
  assert.deepEqual([c.clauses.length, c.clause('turn').words('modifier'), c.relation('in').refs('to')[0]], [1, ['off'], c.nominal('heading')])
  // a bare common noun right after a nominal, made a second object or an apposition, heads that nominal
  assert.deepEqual(of('change the avatar kind to alien').nominal('kind').words('dependent'), ['the', 'avatar'])
  c = of('the marker borders on Revenue trend should be thicker. flip the x axis')
  assert.deepEqual([c.relation('on').refs('to')[0], c.nominal('trend').words('dependent')], [c.nominal('trend'), ['Revenue']])
  // a nominal opened by "no" after a comma at the end of a clause is a remark of its own
  c = of(bird)
  assert.deepEqual([c.relations.some(wire => wire.refs('to')[0] === c.nominal('change')), c.clauses.find(wire => wire.refs('complement')[0] === c.nominal('change')).form], [false, 'fragment'])
  c = of(cat)
  assert.deepEqual([c.clause('stays').refs('complement'), c.clauses.find(wire => wire.refs('complement')[0] === c.nominal('change')).form], [[c.nominal('same')], 'fragment'])
  // "of" after a pronoun or a numeral in letters says of which things that part is
  c = of('hey — remove all but three of them of those five clouds')
  assert.deepEqual(c.relations.filter(wire => wire.words('marker')[0] === 'of').map(wire => wire.refs('from')[0]), [c.nominal('three'), c.nominal('them')])
  // a word the parser could not place, first in the sentence, heads the clause hung beside it; "so" joins the next clause
  c = of(whatIf)
  assert.deepEqual([c.relation('if').refs('from')[0], c.relation('so').refs('from')[0]], [c.clauses.find(wire => wire.refs('complement')[0] === c.nominal('what')), c.clause('put')])
  // a plural noun before an adjective and its noun ends a nominal of its own
  c = of('markers little diamonds')
  assert.deepEqual(c.clauses[0].refs('complement'), [c.nominal('markers'), c.nominal('diamonds')])
  // a compound before a name: its last noun heads it, tied to the name
  c = of('The next thing is to label the x axis Month on the bar chart.')
  assert.deepEqual([c.nominal('axis').words('dependent'), c.relations.some(wire => wire.refs('from')[0] === c.nominal('axis') && wire.refs('to')[0] === c.nominal('Month'))], [['the', 'x'], true])
  // a name after a noun that brings in a new thing is tied to it, also when the parser set it apart or could not read the noun
  c = of('add a pie Second Main Intro')
  assert.deepEqual([c.clauses.length, c.relations[0].refs('from')[0], c.relations[0].refs('to')[0]], [1, c.nominal('pie'), c.nominal('Intro')])
  c = of('add a hert Take 2 260')
  assert.deepEqual([c.clause('add').refs('complement'), c.nominal('260').words('dependent'), c.relations[0].refs('from')[0]], [[c.nominal('hert')], ['Take', '2'], c.nominal('hert')])
  // a word with an object of its own is a verb
  c = of("Let's histogram wait time.")
  assert.deepEqual([c.clause('histogram').form, c.clause('histogram').refs('complement')], ['nonfinite', [c.nominal('time')]])
  // a base form right after an object, taking only a preposition, grades that preposition
  c = of('add a box close beside Slide')
  assert.deepEqual([c.clauses.length, c.clause('add').words('modifier'), c.relation('beside').refs('from')[0]], [1, ['close'], c.clause('add')])
  // a word the raw text writes after a determiner, read as an interjection right after an object, is a word of the clause
  assert.deepEqual(of('point the girl right and have her sit with her legs out on the grass').clause('point').words('modifier'), ['right'])
  // a range of numbers before the noun they count: a relation from the first to the noun
  c = of('for the map, add a scale bar under the figure, marked 0 to 10 m')
  assert.deepEqual([c.clause('marked').refs('complement'), c.relation('to').refs('from')[0], c.relation('to').refs('to')[0]], [[c.nominal('0')], c.nominal('0'), c.nominal('m')])
  // the raw text shows "caviar" to be a noun, "curved" and "small" to be adjectives
  c = of('caviar, please')
  assert.deepEqual(c.clauses[0].refs('complement'), [c.nominal('caviar')])
  c = of('do the callout arrows curved on the revenue trend')
  assert.deepEqual([c.clause('do').form, c.clause('do').words('modifier'), c.clause('do').refs('complement')], ['imperative', ['curved'], [c.nominal('arrows')]])
  // (sixth round: after the colon "bar gap" is the complement of a group of words of its own and "small" its modifier, Rule 5)
  c = of('the missing piece: bar gap small on the sales chart. legend on the right')
  const gap = c.clauses.find(wire => wire.refs('complement').includes(c.nominal('gap')))
  assert.deepEqual([c.nominal('gap').words('dependent'), gap.words('modifier'), c.relations.find(wire => wire.words('marker')[0] === 'on').refs('from')[0]], [['bar'], ['small'], gap])
  // words of address mentioned as content are content; an interjection with an auxiliary is a verb
  c = of('add a paragraph saying Welcome')
  assert.deepEqual([c.clause('saying').refs('complement'), c.clause('saying').words('discourse')], [[c.nominal('Welcome')], []])
  c = of("I'd like a box and three circles in a row")
  assert.deepEqual([c.clause('like').form, c.clause('like').refs('subject'), c.clause('like').refs('complement')[0].type], ['declarative', [c.nominal('I')], 'coordination'])
  c = of('rewrite the paragraph as Thank you for your patience.')
  assert.deepEqual([c.relation('as').refs('to')[0], c.clause('Thank').refs('complement')], [c.clause('Thank'), [c.nominal('you')]])
  c = of('Hello in the first paragraph, bold')
  assert.deepEqual([c.clauses[0].refs('complement'), c.relation('in').refs('from')[0]], [[c.nominal('Hello')], c.nominal('Hello')])
  // a verb under a noun, opened by "to", leaves the first word of a verbless sentence its verb
  assert.equal(of('change Weekly review on Monday at 10:00 and the notes to bring the slides').clause('change').form, 'imperative')
  // the last item of a list that the parser made the root joins its list; "grids on" is a second thing after "with"
  c = of(market)
  const items = c.coordinations.find(wire => wire.refs('conjunct').includes(c.nominal('woman')))
  assert.deepEqual([items.refs('conjunct').includes(c.nominal('breads')), c.relations.some(wire => wire.words('marker')[0] === 'on' && wire.refs('from')[0] === c.nominal('breads'))], [true, true])
  c = of(histogram)
  assert.deepEqual(c.relation('with').refs('to')[0].refs('conjunct'), [c.nominal('values'), c.nominal('grids')])
  // two numbers side by side: the first labels the name before it; a question mark ends a verbless question
  c = of('Hey, make Tractor 2 62 pixels wide.')
  assert.deepEqual([c.relations[0].refs('from')[0], c.relations[0].refs('to')[0], c.nominal('pixels').words('dependent')], [c.nominal('Tractor'), c.nominal('2'), ['62']])
  c = of('how about a poodle instead? — go on')
  assert.deepEqual([c.clauses.map(wire => wire.form), c.relation('about').refs('from')[0]], [['fragment', 'imperative'], c.clauses[0]])
})

test('sixth round: words of time after a nominal, lists of settings, subjects, verbs found again, lists, sentences apart', async () => {
  const chart = "make me a line chart of orders by week first. Where's the top of the curve, and what's the figure at that point?"
  const group = 'add a group with labels North, South and East and values 3, 5 and 8 and layout bar and label Review'
  const meeting = 'add a meeting on Monday at 10:00 with title Quarterly plan and duration 30 and notes bring the slides'
  const scatter = 'Make a scatter plot placing one circle for each orders at its order value and profit for the summary slide, then sort the marks from largest to smallest'
  const tweak = "while you're there, set the arrows medium, that's the tweak; also try the arrow style curved"
  const save = 'a small cat way off on the left, then save the right empty — keeping the rest of the scene as it is'
  const boats = 'spread a few boats across the lake — right there in the picture — that is how the picture goes'
  const pages = 'page 9: bold words; pages 7 and 8: amber grounds; page 0: the picture 3 tall'
  const items = 'add a task list with items "Review draft 9", "Check numbers 9", "Send notes 9"'
  const share = 'the pages 9, 10 and 7 share the one textbox, Lane Works, while the picture takes 7 for its height'
  const swap = 'swap the first and second, then the second and third, and leave it at the step 2 state for now'
  const women = 'a young woman wearing purple glasses over on the right side, and the woman seated on the bench, and that is the scene so far'
  const texts = ['cloud beside the sun next, facing left', chart, group, meeting, 'make it so there is a cloud on top of one per tree',
    'undo one move and say how many shapes remain', scatter, 'set r1 width 180 height 90', tweak, 'count the circles, and if there are more than one, tell me which',
    'Which region advanced the most in revenue?', 'maake the edge of Rack meet the edge of Sample', 'pleese make the two branches joined at a shared child node',
    'ly out the whole picture like a poster layout centred on the subject', 'now snxp Approve and Review to a single row', 'update a grin mouth purple',
    save, boats, 'two ovals — no wait, undo', pages, items, share, swap, women, 'move block 6 two spaces left, then add two blocks next to the block',
    'Please, add a green triangle labelled Jan. Thanks!', 'color the Intro node orange and medium sized', 'I need you to what colour is face a?. I appreciate it.',
    'I want the shading filled-in colour on the sensor contour', 'erase all the stones but the big one can stay', 'out with the trees but the ones beside the house can stay']
  const results = await circuits(spacyDirect, texts)
  const of = text => read(results.get(text).candidates[0].sop)

  // an adverb or an ordinal after a nominal that ends a relation is a word of the clause (time and order)
  let c = of('cloud beside the sun next, facing left')
  assert.deepEqual([c.clauses[0].words('modifier'), c.nominal('sun').words('dependent')], [['next'], ['the']])
  assert.deepEqual([of(chart).clause('make').words('modifier'), of(chart).nominal('week').words('dependent')], [['first'], []])
  // a list of settings after a preposition: each bare noun with its value, joined to the first
  c = of(group)
  assert.deepEqual([c.clause('add').refs('complement'), c.relation('with').refs('to')[0].refs('conjunct')],
    [[c.nominal('group')], [c.nominal('labels'), c.nominal('values'), c.nominal('bar'), c.nominal('Review')]])
  c = of(meeting)
  assert.deepEqual([c.relation('with').refs('to')[0].refs('conjunct'), c.relations.find(wire => wire.refs('to')[0] === c.clause('bring')).refs('from')[0], c.clause('bring').form],
    [[c.nominal('title'), c.nominal('duration'), c.nominal('notes')], c.nominal('notes'), 'imperative'])
  // a subject before the subordinator of its verb is the object of the verb above
  c = of('make it so there is a cloud on top of one per tree')
  assert.deepEqual([c.clause('make').refs('complement'), c.clause('is').refs('subject')], [[c.nominal('it')], [c.nominal('there')]])
  // a numeral counts the word after it; a noun read as a verb after "and" joins the noun before; numbers pair with the noun before them
  c = of('undo one move and say how many shapes remain')
  assert.deepEqual([c.clause('undo').refs('complement'), c.clause('move'), c.nominal('move').words('dependent')], [[c.nominal('move')], undefined, ['one']])
  c = of(scatter)
  assert.deepEqual([c.clause('profit'), c.relation('at').refs('to')[0].refs('conjunct')], [undefined, [c.nominal('value'), c.nominal('profit')]])
  c = of('set r1 width 180 height 90')
  assert.deepEqual(c.relations.map(wire => [wire.refs('from')[0], wire.refs('to')[0]]), [[c.nominal('width'), c.nominal('180')], [c.nominal('width'), c.nominal('height')], [c.nominal('height'), c.nominal('90')]])
  // a dependent clause before a comma opens the clause after it, not one after a semicolon
  c = of(tweak)
  assert.deepEqual(c.relation('while').refs('from')[0], c.clause('set'))
  // "than" links a comparative to a number; "the" determines a superlative
  c = of('count the circles, and if there are more than one, tell me which')
  assert.deepEqual([c.clause('are').words('modifier'), c.relation('than').refs('to')[0]], [['more'], c.nominal('one')])
  assert.deepEqual(of('Which region advanced the most in revenue?').clause('advanced').words('modifier'), ['the', 'most'])
  // verbs found again: a bare infinitive after a singular noun, a lone word before a present form, a particle, an opening adverb
  c = of('maake the edge of Rack meet the edge of Sample')
  assert.deepEqual([c.clause('maake').form, c.clause('meet').form], ['imperative', 'nonfinite'])
  c = of('pleese make the two branches joined at a shared child node')
  assert.deepEqual([c.clause('make').form, c.clause('make').words('discourse'), c.clause('make').refs('subject')], ['imperative', ['pleese'], []])
  c = of('ly out the whole picture like a poster layout centred on the subject')
  assert.deepEqual([c.clause('ly').form, c.clause('ly').words('modifier'), c.clause('ly').refs('complement')], ['imperative', ['out'], [c.nominal('picture')]])
  c = of('now snxp Approve and Review to a single row')
  assert.deepEqual([c.clause('snxp').form, c.clause('snxp').words('modifier'), c.clause('snxp').refs('complement')[0].refs('conjunct')],
    ['imperative', ['now'], [c.nominal('Approve'), c.nominal('Review')]])
  // a determiner opens a nominal that runs to its last noun
  assert.deepEqual(of('update a grin mouth purple').nominal('mouth').words('dependent'), ['a', 'grin'])
  // a word said of an object follows it; "then" before a verb hung beside the group before belongs to that verb's clause
  c = of(save)
  assert.deepEqual([c.clause('save').words('modifier'), c.coordinations[0].words('conjunction')], [['empty'], ['then']])
  // a phrase between two dashes belongs to the clause before them
  c = of(boats)
  assert.deepEqual([c.clause('spread').words('modifier'), c.relation('in').refs('from')[0], c.clause('is').words('modifier')], [['right', 'there'], c.clause('spread'), []])
  // "no wait": a verb about what is said is a clause beside; a learned opener alone after a comma commands
  c = of('two ovals — no wait, undo')
  assert.deepEqual([c.clause('wait').words('discourse'), c.clause('undo').form], [['no'], 'imperative'])
  // a nominal after a semicolon is a group of words of its own
  c = of(pages)
  assert.deepEqual([c.clauses.length, c.coordinations.find(wire => wire.refs('conjunct').length === 3).refs('conjunct')], [3, c.clauses])
  // the items of a list follow one another
  c = of(items)
  assert.deepEqual(c.relations.find(wire => wire.refs('from')[0] === c.nominal('items')).refs('to')[0].refs('conjunct'),
    [c.nominal('Review draft 9'), c.nominal('Check numbers 9'), c.nominal('Send notes 9')])
  c = of(share)
  assert.deepEqual(c.coordinations[0].refs('conjunct'), [c.nominal('9'), c.nominal('10'), c.nominal('7')])
  // a pair opened by "then" after the object is a second thing the verb does; its "and" joins the pair
  c = of(swap)
  const second = c.clauses.find(wire => wire.form === 'fragment')
  assert.deepEqual([second.refs('ellipsis'), second.refs('complement')[0].words('conjunction')], [[c.clause('swap')], ['and']])
  c = of(women)
  assert.deepEqual(c.coordinations.find(wire => wire.refs('conjunct').includes(c.nominal('woman'))).words('conjunction'), ['and'])
  // a measure with a word of place after the object measures the verb; thanks after a full stop is a sentence of its own
  c = of('move block 6 two spaces left, then add two blocks next to the block')
  assert.deepEqual([c.clause('move').words('modifier'), c.clause('move').refs('complement')], [['left'], [c.nominal('block'), c.nominal('spaces')]])
  c = of('Please, add a green triangle labelled Jan. Thanks!')
  assert.deepEqual([c.nominal('Jan').words('dependent'), c.clauses.at(-1).words('discourse')], [[], ['Thanks']])
  // a bare noun and an adjective joined after the object are what the object is made
  assert.deepEqual(of('color the Intro node orange and medium sized').clause('color').words('modifier'), ['orange', 'medium', 'sized'])
  // "a" with nothing after it names the noun before it; a hyphened participle is an adjective; a subordinator opens a clause
  c = of('I need you to what colour is face a?. I appreciate it.')
  assert.deepEqual([c.clause('is').refs('complement'), c.relations.find(wire => wire.refs('to')[0] === c.nominal('a')).refs('from')[0]], [[c.nominal('colour')], c.nominal('face')])
  c = of('I want the shading filled-in colour on the sensor contour')
  assert.deepEqual([c.clauses.length, c.clause('want').refs('complement'), c.nominal('colour').words('dependent')], [1, [c.nominal('shading'), c.nominal('colour')], ['filled-in']])
  // the nominal before the auxiliary of a verb is its subject, and the conjunction joins its clause to the words before
  c = of('erase all the stones but the big one can stay')
  assert.deepEqual([c.clause('erase').refs('complement'), c.clause('stay').refs('subject'), c.coordinations[0].words('conjunction')], [[c.nominal('stones')], [c.nominal('one')], ['but']])
  c = of('out with the trees but the ones beside the house can stay')
  assert.deepEqual([c.clauses.map(wire => wire.form), c.clause('stay').refs('subject')], [['fragment', 'declarative'], [c.nominal('ones')]])
})

test('seventh round: gapping, measures and items set off by commas, linking words, adjectives of their own verb, numbers, "of"', async () => {
  const notes = 'set the room of Weekly review to Cedar room and the notes to bring the slides'
  const house = 'update the house, at y 90, 160 wide, 100 high, coloured red, labelled Home'
  const keep = 'Keep the legend rule for the diagram I have open, plus show the values on this chart.'
  const compose = 'a small grey cat sitting in the bottom left corner, then compose the page as a 1950s advertisement layout, with the subject low and the title space clear above it — the figures and objects themselves keep their shapes'
  const line = 'line thinner; also do the marker borders thicker on the revenue trend. font bigger'
  const pages = 'page 9: bold words; pages 7 and 8: amber grounds; page 0: the picture 3 tall'
  const texts = [notes, house, 'last two, same step', 'b2 first, all other blocks in their existing order', 'can you nudge Payment underneath Pack', keep,
    'our sun left to right for me', compose, line, 'place a tree 400 about two hundred sixty', 'Put a calllout on the best store of the store bars', pages]
  const results = await circuits(spacyDirect, texts)
  const of = text => read(results.get(text).candidates[0].sop)

  // a conjunct that repeats the linking word of the clause before it shares its verb: "[set] the notes to …"
  let c = of(notes)
  const notesPart = c.clauses.find(wire => wire.refs('complement').includes(c.nominal('notes')))
  assert.deepEqual([notesPart.form, notesPart.refs('ellipsis')[0], c.coordinations[0].refs('conjunct')], ['fragment', c.clause('set'), [c.clause('set'), notesPart]])
  // a measure set off by a comma is a nominal of the clause, its adjective a modifier
  c = of(house)
  assert.deepEqual([c.clause('update').words('modifier'), c.clause('update').refs('complement')], [['wide', 'high'], [c.nominal('house'), c.nominal('160'), c.nominal('100')]])
  // the words before a comma that end in a number or a name are an item of their own
  c = of('last two, same step')
  assert.deepEqual([c.clauses[0].refs('complement'), c.nominal('two').words('dependent')], [[c.nominal('two'), c.nominal('step')], ['last']])
  c = of('b2 first, all other blocks in their existing order')
  assert.deepEqual([c.clauses[0].refs('complement'), c.clauses[0].words('modifier')], [[c.nominal('b2'), c.nominal('blocks')], ['first']])
  // an adverb between an object and a noun links the noun: a preposition
  c = of('can you nudge Payment underneath Pack')
  assert.deepEqual([c.relation('underneath').refs('from')[0], c.relation('underneath').refs('to')[0]], [c.clause('nudge'), c.nominal('Pack')])
  // an adjective after the verb of a relative clause is said by that verb
  c = of(keep)
  assert.deepEqual([c.clause('have').words('modifier'), c.clause('Keep').words('modifier')], [['open'], []])
  // a preposition made a root of its own hangs on the sentence before it
  c = of('our sun left to right for me')
  assert.deepEqual([c.clauses.length, c.relation('for').refs('from')[0]], [1, c.nominal('sun')])
  // a noun joined to an adjective said of a noun is joined to that noun, inside the phrase of "with"
  c = of(compose)
  assert.deepEqual([c.relation('with').refs('to')[0].refs('conjunct'), c.clause('compose').refs('complement'), c.nominal('subject').words('dependent')],
    [[c.nominal('subject'), c.nominal('space')], [c.nominal('page')], ['the', 'low']])
  // a noun before the adjective of a part with no verb is the thing it is said of
  c = of(line)
  assert.deepEqual([c.clauses[0].refs('complement'), c.clauses[0].words('modifier')], [[c.nominal('line')], ['thinner']])
  // a number in figures across an adverb of another number stands by itself
  c = of('place a tree 400 about two hundred sixty')
  assert.deepEqual([c.nominal('400').words('dependent'), c.nominal('sixty').words('dependent')], [[], ['about', 'two', 'hundred']])
  // "of" governs the whole nominal after it
  c = of('Put a calllout on the best store of the store bars')
  assert.deepEqual([c.relation('of').refs('from')[0], c.relation('of').refs('to')[0], c.nominal('bars').words('dependent')], [c.nominal('store'), c.nominal('bars'), ['the', 'store']])
  // a second number after a conjunction joins the first number, not the noun
  c = of(pages)
  const pair = c.coordinations.find(wire => wire.words('conjunction')[0] === 'and')
  assert.deepEqual(pair.refs('conjunct').map(wire => wire.words('head')[0]), ['7', '8'])
})

test('eighth round: command verbs found again, verbs of causing, "do" before no verb, words that say how a thing should be', async () => {
  const texts = ['tunr the tall kid beside the house to face right', 'raverse the whole row', 'please label number n4 "Risk"',
    'darw a tall man facing right leaning against the tree on the left', 'undo the last change: the chart back upright', 'space evenly',
    'Now paint values below 50 red on Monthly sales.', 'est block 14 below block 13, next est block 14 left and down until it is even with block 12',
    'pllace Path alongside Pond for the final layout and keep Gate exactly where it is', 'er mirror uh the tail of the dog sideways',
    'amke everything look like a watercolour painting', 'hvae the girl by the garden look at the sun',
    'do the error bar caps magenta on the sales chart', 'do the marker outlines green and thicker on the order scatter',
    'line magenta', 'turn all the links navy', 'g1 medium',
    'convert the first paragraph to a heading of level 3: text Revised paragraph, name Summary, justified', 'that Water grey could do with some cheering up']
  const results = await circuits(spacyDirect, texts)
  const of = text => read(results.get(text).candidates[0].sop)
  const command = (text, verb, head) => {
    const c = of(text), clause = c.clause(verb)
    assert.equal(clause.form, 'imperative', text)
    if (head) assert.equal(clause.refs('complement')[0], c.nominal(head), text)
    return c
  }
  // a command verb the tagger read as no verb: before an infinitive or a participle of its object, a misspelling of a
  // frequent opener, after a word said to the listener, with its object hung outside its clause, before an adverb it takes
  command(texts[0], 'tunr', 'kid')
  command(texts[1], 'raverse', 'row')
  command(texts[2], 'label', 'number')
  command(texts[3], 'darw', 'man')
  command(texts[4], 'undo', 'change')
  assert.deepEqual(command(texts[5], 'space').clause('space').words('modifier'), ['evenly'])
  assert.deepEqual(command(texts[6], 'paint', 'values').clause('paint').words('modifier'), ['Now'])
  let c = of(texts[7])
  assert.equal(c.clauses.filter(wire => wire.words('verb')[0] === 'est').length, 2)
  command(texts[8], 'pllace', 'Path')
  command(texts[9], 'mirror', 'tail')
  // a verb of causing before a nominal and a base form
  for (const [text, verb, later, subject] of [[texts[10], 'amke', 'look', 'everything'], [texts[11], 'hvae', 'look', 'girl']]) {
    c = command(text, verb)
    assert.deepEqual([c.clause(later).form, c.clause(later).refs('subject')[0]], ['nonfinite', c.nominal(subject)])
  }
  // "do" before a noun or an adjective made the head
  assert.deepEqual(command(texts[12], 'do', 'caps').clause('do').words('modifier'), ['magenta'])
  assert.deepEqual(command(texts[13], 'do', 'outlines').clause('do').words('modifier'), ['green', 'thicker'])
  // a word that says how a thing should be, after its noun
  c = of(texts[14])
  assert.deepEqual([c.clauses[0].refs('complement')[0], c.clauses[0].words('modifier')], [c.nominal('line'), ['magenta']])
  assert.deepEqual(command(texts[15], 'turn', 'links').clause('turn').words('modifier'), ['navy'])
  assert.deepEqual(of(texts[16]).clauses[0].words('modifier'), ['medium'])
  // not in a list of settings after a colon, nor of a subject
  assert.ok(!of(texts[17]).clauses.some(wire => wire.words('verb')[0] === 'name'))
  assert.deepEqual(of(texts[18]).clauses[0].words('modifier'), [])
})

test('ninth round: phrases after a list, purpose clauses with "so", names and settings after a noun, measures, adjectives with "the", "how about"', async () => {
  const texts = ['I want a pie chart of 40 and 60 for Q1 and Q2 above the table', 'the first and the last, the ones at the ends, should swap',
    'so it looks windy, spin the crown on the tree 135°', 'so they look at each other, make that girl face right', 'so straighten it',
    'so the review step became approval, update the list to numbered items Draft and Approve, with only the first item checked',
    'change a node Backup brown large', 'add a retangle 2 white medium', "set the gaps between the bars wider, that's the tweak. and then give it the title Q2 sales",
    'could you move the first pair right one and then return it left one', 'quick one: add panel labels A, B and C above the three panels, for the final version',
    'i need you to rotate the first two one place right and then one place back left, so they end unchanged',
    'now set our sun face the left', 'the original', 'can you make the shape a little bigger', 'how about larger axis labels?']
  const results = await circuits(spacyDirect, texts)
  const of = text => read(results.get(text).candidates[0].sop)
  // a phrase or a renaming nominal after the last item of a list goes with the whole list
  let c = of(texts[0])
  const list = c.coordinations.find(wire => wire.refs('conjunct').includes(c.nominal('40')))
  assert.equal(c.relation('for').refs('from')[0], list)
  c = of(texts[1])
  assert.equal(c.relations.find(wire => wire.refs('to')[0] === c.nominal('ones')).refs('from')[0].type, 'coordination')
  // "so" before a clause with a subject, a comma and a command: what the command is for
  for (const [text, verb, purpose] of [[texts[2], 'spin', 'looks'], [texts[3], 'make', 'look']]) {
    c = of(text)
    assert.deepEqual([c.relation('so').refs('from')[0], c.relation('so').refs('to')[0]], [c.clause(verb), c.clause(purpose)], text)
    assert.equal(c.coordinations.length, 0, text)
  }
  assert.deepEqual(of(texts[4]).clause('straighten').words('discourse'), ['so'])
  assert.equal(of(texts[5]).relation('so'), undefined)
  // a name and the words that say how the thing should be, after a noun opened by a determiner
  c = of(texts[6])
  assert.deepEqual([c.clause('change').refs('complement'), c.clause('change').words('modifier')], [[c.nominal('node')], ['brown', 'large']])
  assert.equal(c.relations[0].refs('to')[0], c.nominal('Backup'))
  c = of(texts[7])
  assert.deepEqual([c.clause('add').refs('complement'), c.clause('add').words('modifier')], [[c.nominal('retangle')], ['white', 'medium']])
  assert.deepEqual(of(texts[8]).nominal('sales').words('dependent'), ['Q2'])
  // an adjective before a bare numeral says how the verb goes; two numerals side by side are two nominals
  c = of(texts[9])
  assert.deepEqual(c.clause('move').words('modifier'), ['right'])
  assert.ok(c.clause('return').words('modifier').includes('left'))
  assert.deepEqual(c.nominals.filter(wire => wire.words('head')[0] === 'one').map(wire => wire.words('dependent')), [[], []])
  assert.ok(!of(texts[10]).clause('add').words('modifier').includes('quick'))
  c = of(texts[11])
  assert.deepEqual(c.clause('rotate').refs('complement'), [c.nominal('two'), c.nominals.find(wire => wire.words('head')[0] === 'place')])
  // an adjective with "the" and no noun is a nominal; "a little" before a graded word is left alone
  c = of(texts[12])
  assert.deepEqual(c.nominal('left').words('dependent'), ['the'])
  assert.equal(of(texts[13]).nominal('original').words('dependent')[0], 'the')
  assert.equal(of(texts[14]).nominal('little'), undefined)
  // "about" of "how about" marks the nominal after it
  c = of(texts[15])
  assert.deepEqual([c.relation('about').refs('to')[0], c.nominal('labels').words('dependent')], [c.nominal('labels'), ['larger', 'axis']])
})

test('spacy-beam leaves an attachment unsettled where the parses of the beam disagree', async () => {
  const text = "I'd like the marker outlines thick on the order scatter"
  const direct = read((await circuits(spacyDirect, [text])).get(text).candidates[0].sop)
  assert.equal(direct.relation('on').attachment, undefined)
  const result = (await circuits(spacyBeam, [text])).get(text)
  const beam = read(result.candidates[0].sop)
  assert.equal(beam.relation('on').attachment, 'ambiguous')
  // Rule 2: an unsettled relation starts at the clause
  assert.equal(beam.relation('on').refs('from')[0], beam.clause('like'))
  assert.equal(beam.relation('on').refs('to')[0], beam.nominal('scatter'))
  assert.equal(result.candidates[0].unsettled, 1)
  assert.equal(result.candidates[0].source, 'greedy')
  // where the beam agrees, nothing is marked: one circuit, the same as spacy-direct
  const settled = 'the box was moved by Ana'
  assert.equal((await circuits(spacyBeam, [settled])).get(settled).candidates[0].sop, (await circuits(spacyDirect, [settled])).get(settled).candidates[0].sop)
})

test('spacy-beam falls back on a parse of the beam when the greedy parse leaves words unplaced', async () => {
  const source = 'Add the box.'
  const lexical = [['Add', 0, 'VERB', 'VB'], ['the', 4, 'DET', 'DT'], ['box', 8, 'NOUN', 'NN'], ['.', 11, 'PUNCT', '.']]
  const parse = arcs => lexical.map(([text, start, pos, tag], i) => ({i, text, start, end: start + text.length, pos, tag, lemma: text.toLowerCase(), dep: arcs[i][0], head: arcs[i][1]}))
  // the greedy parse hangs the noun on the verb by a relation that gives a noun no place
  const greedy = parse([['ROOT', 0], ['det', 2], ['mark', 0], ['punct', 0]])
  const complete = parse([['ROOT', 0], ['det', 2], ['dobj', 0], ['punct', 0]])
  const provider = alternatives => ({async open() { return {metadata: {}, parseBeam: async () => ({tokens: greedy, alternatives}), parse: async () => greedy, close: async () => {}} }})
  const propose = async alternatives => {
    const reader = await createReader({strategy: spacyBeam, syntaxModel: provider(alternatives)})
    try { return await reader.propose(source) } finally { await reader.close() }
  }
  const fallback = await propose([{score: 0.3, tokens: greedy}, {score: 0.7, tokens: complete}])
  assert.equal(fallback.candidates.length, 1)
  assert.equal(fallback.candidates[0].source, 'beam')
  assert.equal(fallback.candidates[0].beamScore, 0.7)
  const c = read(fallback.candidates[0].sop)
  assert.deepEqual([c.clause('Add').form, c.clause('Add').refs('complement')], ['imperative', [c.nominal('box')]])
  // with no better parse the greedy one stands, still as one valid circuit that covers every word
  const alone = await propose([{score: 1, tokens: greedy}])
  assert.equal(alone.candidates.length, 1)
  assert.equal(alone.candidates[0].source, 'greedy')
  assert.deepEqual(alone.candidates[0].loose, ['box'])
  assert.equal(alone.candidates[0].check.valid, true)
  // direct access to the choice
  assert.equal(beamCircuit(source, greedy, [{score: 0.7, tokens: complete}]).source, 'beam')
  assert.equal(directCircuit(source, complete).sop, fallback.candidates[0].sop)
})

test('a failure of the parser is an error, never a circuit', async () => {
  const failing = {async open() { return {metadata: {}, parse: async () => { throw new Error('parser stopped') }, parseBeam: async () => { throw new Error('parser stopped') }, close: async () => {}} }}
  for (const strategy of strategies) {
    const reader = await createReader({strategy, syntaxModel: failing})
    const result = await reader.propose('move it')
    assert.deepEqual([result.candidates, result.error], [[], 'parser stopped'], strategy.name)
    const empty = await reader.propose('   ')
    assert.deepEqual(empty.candidates, [])
    // a message with no words gets no circuit
    const marks = await (await createReader({strategy, syntaxModel: {async open() {
      const tokens = [{i: 0, text: '?', start: 0, end: 1, pos: 'PUNCT', tag: '.', dep: 'ROOT', head: 0, lemma: '?'}]
      return {metadata: {}, parse: async () => tokens, parseBeam: async () => ({tokens, alternatives: []}), close: async () => {}}
    }}})).propose('?')
    assert.deepEqual([marks.candidates, marks.error], [[], 'The message has no words.'], strategy.name)
    await reader.close()
  }
  await assert.rejects(createReader({strategy: spacyBeam, syntaxModel: {async open() { return {metadata: {}, parse: async () => [], close: async () => {}} }}}), /requires a dependency backend with parseBeam/u)
})

test('the strategies read nothing outside this package and write no other schema', () => {
  const files = ['neural-dependencies/index.mjs', 'neural-dependencies/syntax-circuit.mjs', 'spacy-direct/index.mjs', 'spacy-direct/clause-repairs.mjs',
    'spacy-direct/word-repairs.mjs', 'spacy-beam/index.mjs', 'spacy/index.mjs']
  for (const file of files) {
    const source = readFileSync(new URL('../strategies/' + file, import.meta.url), 'utf8')
    assert.doesNotMatch(source, /knowledgeDir|sop-knowledge-worlds|SOP_KNOWLEDGE_DIR|check-analysis|schemaPaths|worldPaths/u, file)
    assert.doesNotMatch(source, /['"`]nlu\.|w\.request|project\.mjs|nominal-roles|predicate-attachments/u, file)
    for (const [, from] of source.matchAll(/^import .* from '([^']+)'/gmu)) {
      assert.match(from, /^(?:node:(?:child_process|readline|url)|\.\.\/\.\.\/lib\/syntax\.mjs|\.\.?\/(?:neural-dependencies|spacy-direct|spacy-beam)\/[a-z-]+\.mjs|\.\/[a-z-]+\.mjs)$/u, `${file} imports ${from}`)
    }
  }
})

